     if (ldapGroup == null) {
       this.ldapGroup = null;
     } else {
       this.ldapGroup = ldapGroup ? 1 : 0;
     }
   }


-  public void setgroupType(GroupType groupType) {
+  public void setGroupType(GroupType groupType) {
     this.groupType = groupType;
+    setLdapGroup(groupType == GroupType.LDAP);
